import sys

def main():
    data = sys.stdin.read().split()
    K, M, N = int(data[0]), int(data[1]), int(data[2])
    a = [int(x) for x in data[3:3 + K]]
    b = [int(x) for x in data[3 + K:3 + 2 * K]]
    T = min(M, K, N)
    NEG = -1
    # dp[last][t][s]: best payout with t tasks, s switches, last task from startup `last`
    dp = [[[NEG] * (T + 1) for _ in range(T + 1)] for _ in range(2)]
    best = 0
    for i in range(K):
        pay = (a[i], b[i])
        new = [[row[:] for row in dp[0]], [row[:] for row in dp[1]]]
        for last in range(2):
            v = pay[last]
            if new[last][1][0] < v:
                new[last][1][0] = v
        for last in range(2):
            for t in range(1, T):
                row = dp[last][t]
                for s in range(0, t):
                    cur = row[s]
                    if cur < 0:
                        continue
                    for nxt in range(2):
                        if nxt == last:
                            ns = s
                        else:
                            ns = s + 1
                        if t + 1 + ns > N:
                            continue
                        val = cur + pay[nxt]
                        if new[nxt][t + 1][ns] < val:
                            new[nxt][t + 1][ns] = val
        dp = new
    for last in range(2):
        for t in range(1, T + 1):
            for s in range(t):
                if dp[last][t][s] > best:
                    best = dp[last][t][s]
    print(best)

